style.css:
@-moz-document domain("youtube.com") {
html {
        background: url("https://www.animeexplained.com/wp-content/uploads/2023/11/invincibles-all-marks-explained-e1699612838999.webp") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    body, #page-manager, ytd-app, ytd-masthead, ytd-browse, ytd-watch-flexy {
        background: transparent !important;
    }

    ytd-page-manager, ytd-browse, ytd-watch-flexy, #content, #columns, #secondary {
        background-color: black !important;
    }

    ytd-video-primary-info-renderer,
    ytd-video-secondary-info-renderer,
    ytd-comments,
    ytd-item-section-renderer,
    ytd-rich-grid-media,
    ytd-rich-item-renderer,
    ytd-thumbnail,
    ytd-playlist-panel-video-renderer,
    ytd-playlist-video-renderer {
        color: white !important;
        text-shadow: 2px 2px 5px black !important;
    }

    ytd-reel-shelf-renderer {
        background-color: black !important;
        padding: 10px !important;
        border-radius: 10px !important;
    }
}
